node --input-type=module -e '
import { decideWhatsApp as d } from "./bot.mjs";
const T = "1767272400"; // 2026-01-01T13:00:00Z
const at = (ms) => new Date(Date.parse("2026-01-01T13:00:00Z") + ms);
const H = 3600e3;
const cases = [
  ["text, not opted in, open window", { type: "text", contact: { optedIn: false, lastInboundTimestamp: T } }, at(1*H), "not_opted_in"],
  ["template, not opted in", { type: "template", contact: { optedIn: false, lastInboundTimestamp: null } }, at(0), "not_opted_in"],
  ["template, opted in, never wrote", { type: "template", contact: { optedIn: true, lastInboundTimestamp: null } }, at(0), null],
  ["template, opted in, window closed", { type: "template", contact: { optedIn: true, lastInboundTimestamp: T } }, at(100*H), null],
  ["text, opted in, never wrote", { type: "text", contact: { optedIn: true, lastInboundTimestamp: null } }, at(0), "no_inbound_message"],
  ["text, 23h59m59s after", { type: "text", contact: { optedIn: true, lastInboundTimestamp: T } }, at(24*H - 1000), null],
  ["text, exactly 24h after", { type: "text", contact: { optedIn: true, lastInboundTimestamp: T } }, at(24*H), "customer_service_window_closed"],
  ["text, 3 days after", { type: "text", contact: { optedIn: true, lastInboundTimestamp: T } }, at(72*H), "customer_service_window_closed"],
  ["text, malformed timestamp", { type: "text", contact: { optedIn: true, lastInboundTimestamp: "2026-01-01" } }, at(0), "invalid_inbound_timestamp"],
  ["text, numeric timestamp", { type: "text", contact: { optedIn: true, lastInboundTimestamp: 1767272400 } }, at(0), "invalid_inbound_timestamp"],
  ["unknown type", { type: "image", contact: { optedIn: true, lastInboundTimestamp: T } }, at(0), "unknown_message_type"],
  ["missing contact", { type: "text" }, at(0), "not_opted_in"],
];
let fail = 0;
for (const [name, msg, now, want] of cases) {
  const got = d(msg, now);
  const ok = want === null ? got.allowed === true && got.reason === null : got.allowed === false && got.reason === want;
  if (!ok) fail++;
  console.log(ok ? "PASS" : "FAIL", name, JSON.stringify(got));
}
try { d({ type: "text", contact: { optedIn: true, lastInboundTimestamp: T } }, "x"); console.log("FAIL bad now did not throw"); fail++; } catch (e) { console.log("PASS bad now throws:", e.message); }
console.log(fail ? `${fail} FAILED` : "all passed");
process.exit(fail ? 1 : 0);
'

